void MoneyBoxSys_Update(FieldSystem *fieldSystem, Window *window) {
    FillWindowPixelRect(window, 15, 0, 16, 10 * 8, 4 * 8 - 16);

    MsgData *messageLoader = NewMsgDataFromNarc(MSGDATA_LOAD_DIRECT, (enum NarcId)27, (enum TextBank)435, HEAP_ID_FIELD1);
    MessageFormat *stringTemplate = MessageFormat_New(HEAP_ID_FIELD1);
    String *string = String_New(16, HEAP_ID_FIELD1);
    String *fmtString = NewString_ReadMsgData(messageLoader, 31);
    u32 money = PlayerProfile_GetMoney(Save_PlayerData_GetProfile(fieldSystem->saveData));

    BufferIntegerAsString(stringTemplate, 0, money, 6, PRINTING_MODE_RIGHT_ALIGN, CHARSET_MODE_EN);
    StringExpandPlaceholders(stringTemplate, string, fmtString);

    u32 printerOffset = (10 * 8) - FontID_String_GetWidth(FONT_SYSTEM, string, 0);

    AddTextPrinterParameterized(window, FONT_SYSTEM, string, printerOffset, 16, 0xFF, 0L);
    String_Delete(fmtString);
    String_Delete(string);
    MessageFormat_Delete(stringTemplate);
    DestroyMsgData(messageLoader);
    ScheduleWindowCopyToVram(window);
}
